use vstd::prelude::*;

verus! {

    /// A pure specification function that reverses a sequence.
    spec fn rev_seq<T: Copy + Permute>(s: Seq<T>) -> Seq<T>
        decreases s
    {
        if s.is_empty() {
            Seq::empty()
        } else {
            Seq::singleton(s.index(s.len() - 1)) +
                rev_seq(s.slice(0, s.len() - 1))
        }
    }

    /// In-place reversal of a vector of u64s.
    /// On return, the vector's length is unchanged, and its contents
    /// are the reverse of the original.
    fn reverse(v: &mut Vec<u64>)
        ensures
            // length is preserved
            v@.len() == old(v@).len(),
            // for every index i in [0, n), v[i] == old(v)[n-1-i]
            forall |i: nat|
                i < v@.len() ==>
                    v@.index(i) == old(v@).index(old(v@).len() - 1 - i)
    {
        // first clone out the original contents
        let old_v = v.clone();
        let n = old_v.len(); // n = old(v@).len()

        // clear out v to build the reversed contents
        v.clear();

        let mut i: usize = 0;
        // each iteration we push old_v[n-1-i] onto v,
        // so after i steps, v@ has length i and
        // v@[0..i] = old_v@[(n-i..n)] in reverse order.
        while i < n
            invariant
                i <= n,
                v@.len() == i,
                forall |k: nat|
                    k < i ==>
                        v@.index(k) == old_v@.index(n - 1 - k),
            decreases n - i
        {
            let idx = n - 1 - i;
            v.push(old_v[idx]);
            i += 1;
        }
        // at this point v.len() == n and
        // ∀ k < n. v@.index(k) == old_v@.index(n-1-k),
        // but old_v@ is precisely the original v@, so we are done.
    }

}

